DELIMITER //
CREATE PROCEDURE `jurnal_bdp`(
	IN `abulan` INT,
	IN `atahun` INT,
	IN `atanggal` DATE



)
BEGIN
declare arekpersediaanbdp,arekpersediaan varchar(8);
declare anilpersediaanbdp double precision;
declare anomor2 varchar(20);
set arekpersediaan = '17.001';
set arekpersediaanbdp = '17.002';

if abulan = 12 then 
select sum(mst_stok_out*if(mst_avgcost>0,mst_avgcost,mst_hargabeli)) into anilpersediaanbdp from tmasterstok 
where mst_noreferensi like '%DO%' AND month(mst_tanggal)=abulan
and year(mst_tanggal)=atahun
and mst_noreferensi not in (select fp_do_nomor from tfp_hdr where fp_tanggal < str_to_date(CONCAT(1,'/1/',ATAHUN+1),'%m/%d/%Y'));
else
select sum(mst_stok_out*if(mst_avgcost>0,mst_avgcost,mst_hargabeli)) into anilpersediaanbdp from tmasterstok 
where mst_noreferensi like '%DO%' AND month(mst_tanggal)=abulan
and year(mst_tanggal)=atahun
and mst_noreferensi not in (select fp_do_nomor from tfp_hdr where fp_tanggal < str_to_date(CONCAT(ABULAN+1,'/1/',ATAHUN),'%m/%d/%Y'));
end if;
 set anomor2 = concat('99.BDP.',CAST(abulan AS CHAR(2)),CAST(atahun AS CHAR(4)));

 delete from tjurnal where jur_no = anomor2;
 delete from tjurnalitem where jurd_jur_no = anomor2;
 
 values  (atanggal,'Jurnal BDP ',anomor2,'otomatis',1,now(),'Admin');

  values (anomor2,arekpersediaan,0,anilpersediaanbdp,1) ;
  values (anomor2,arekpersediaanbdp,anilpersediaanbdp,0,1) ;

END//
