)
BEGIN
declare apersediaan,afreight,appn_masukan,ahutang,apotongan double;
declare anomor2 varchar(20);



select 
 SUM((SELECT SUM((invd_harga*invd_qty)*(100-invd_discpr)/100) from tinv_dtl where invd_inv_nomor=inv_nomor )) persediaan,
 sum(inv_freight) freight,
 sum(inv_taxamount) ppn_masukan,
 sum(inv_amount) hutang,
  sum((inv_disc_fakturpr/100*(SELECT SUM((invd_harga*invd_qty)*(100-invd_discpr)/100) from tinv_dtl where invd_inv_nomor=inv_nomor ))
+ inv_disc_faktur) potongan_pembelian  into apersediaan,afreight,appn_masukan,ahutang,apotongan
 from tinv_hdr  where month(inv_tanggal)=abulan and year(inv_tanggal)=atahun;
 
 set anomor2 = concat('INV.',CAST(abulan AS CHAR(2)),CAST(atahun AS CHAR(4)));

 delete from tjurnal where jur_no = anomor2;
 delete from tjurnalitem where jurd_jur_no = anomor2;
 
 values  (atanggal,'Jurnal Pembelian',anomor2,'otomatis',1,now(),'Admin');
 
    
  values (anomor2,'17.001',apersediaan,0,1) ;
  
  values (anomor2,'16.001',appn_masukan,0,1) ;
  
  values (anomor2,'23.015',afreight,0,1) ;

  
  values (anomor2,'19.002',0,ahutang,1) ;
  
  values (anomor2,'21.005',0,apotongan,1) ;
    
END//
