CREATE PROCEDURE `jurnal_penjualan`(
	IN `abulan` INT,
	IN `atahun` INT,
	IN `atanggal` DATE




)
BEGIN



declare aBDP,abiayapromosi,ahutangbiayapromosi,arekongkir,arekpersediaan,arekdiscpenjualan,arekbpp,arekpotongan,arekppn,arekpiutang,arekpenjualan,arekpiutangcn,abiayacn varchar(8);
declare anilpersediaanBDP,anilpersediaan,anet,apiutang,apiutangcn,appn,adiscpenjualan,aongkir,acn,apromosi double precision;
declare anomor2 varchar(20);

set arekbpp = '26.001';

set arekpenjualan= '21.001'; 
set arekppn = '19.005'; 
set arekongkir = '23.008';  
set arekpotongan = '21.004'; 
set arekpiutang = '14.001'; 

set abiayapromosi = '24.004';
set ahutangbiayapromosi = '19.008';

set arekpiutangcn = '14.003';
set abiayacn = '21.004';
set aBDP = '17.002';
set arekpersediaan = '17.001';


select sum(if(mst_avgcost>0,mst_avgcost,mst_hargabeli)*mst_stok_out) into anilpersediaan from AMPersada.tmasterstok 
INNER join AMPersada.tfp_hdr on fp_do_nomor = mst_noreferensi
inner join AMPersada.tdo_hdr on do_nomor=fp_do_nomor 
where month(fp_tanggal)=abulan and year(fp_tanggal) = atahun
and month(mst_tanggal) = abulan;

select sum(if(mst_avgcost>0,mst_avgcost,mst_hargabeli)*mst_stok_out) into anilpersediaanBDP from AMPersada.tmasterstok 
INNER join AMPersada.tfp_hdr on fp_do_nomor = mst_noreferensi
inner join AMPersada.tdo_hdr on do_nomor=fp_do_nomor 
where month(fp_tanggal)=abulan and year(fp_tanggal) = atahun
and month(mst_tanggal) <> abulan;

select sum((((fp_amount-fp_freight)-fp_taxamount)+fp_disc_faktur)/(100-fp_disc_fakturpr)*100) net,
sum(if(so_sls_kode<>'SLS-999' ,FP_amount,0)) piutang,sum(if(so_sls_kode='SLS-999' ,FP_amount,0)) piutangcn,sum(FP_taxamount) ppn,
sum(((Fp_disc_fakturpr*((((fp_amount-fp_freight)-fp_taxamount)+fp_disc_faktur)/(100-fp_disc_fakturpr)*100))/100) + fp_disc_faktur) discpenjualan,
sum(fp_freight) ongkir,
sum(fp_cn) cn,
sum(((Fp_biayapr*((fp_amount-fp_taxamount-ifnull((select sum(retj_amount) from AMPersada.tretj_hdr  where retj_fp_nomor = fp_nomor),0) ))/100) + fp_biayarp)) promosi
into anet,apiutang,apiutangcn,appn,adiscpenjualan,aongkir,acn,apromosi
from AMPersada.tfp_hdr 
inner join AMPersada.tdo_hdr on do_nomor=fp_do_nomor
inner join AMPersada.tso_hdr on so_nomor=do_so_nomor
where month(fp_tanggal)=abulan and year(fp_tanggal) = atahun;

 set anomor2 = concat('99.FP.',CAST(abulan AS CHAR(2)),CAST(atahun AS CHAR(4)));

 delete from tjurnal where jur_no = anomor2;
 delete from tjurnalitem where jurd_jur_no = anomor2;
 
 values  (atanggal,'Jurnal Penjualan Solo',anomor2,'otomatis',1,now(),'Admin');

  values (anomor2,arekpersediaan,0,anilpersediaan,1) ;
  values (anomor2,arekbpp,anilpersediaan,0,1) ;


  values (anomor2,abdp,0,anilpersediaanbdp,1) ;
  values (anomor2,arekbpp,anilpersediaanbdp,0,1) ;  
  

    
  values (anomor2,arekpenjualan,0,anet,1) ;
  values (anomor2,arekongkir,0,aongkir,1) ;
  values (anomor2,arekppn,0,appn,1) ;
    
  values (anomor2,arekpiutang,apiutang,0,1) ;
  values (anomor2,arekpotongan,adiscpenjualan,0,1) ;
  values (anomor2,arekpiutangcn,apiutangcn,0,1) ;


  values (anomor2,arekpiutangcn,0,acn,1) ;
  values (anomor2,abiayacn,acn,0,1) ;

  values (anomor2,ahutangbiayapromosi,0,apromosi,1) ;
  values (anomor2,abiayapromosi,apromosi,0,1,'D0002') ;
  
  



END//
