-- Dumping structure for procedure ampersada.sp_kp_cr
DELIMITER //
CREATE PROCEDURE `sp_kp_cr`(IN p_byc_nomor VARCHAR(20), IN p_fp_nomor VARCHAR(20))
BEGIN
  DECLARE v_sls VARCHAR(10);
  DECLARE v_cus CHAR(10);
  DECLARE v_tgl DATE;
  DECLARE v_jt  DATE;
  DECLARE v_bayar DOUBLE;

  DELETE FROM 	kartupiutang
   WHERE kp_src = CONCAT('CR|', p_byc_nomor, '|', p_fp_nomor);

  SET v_cus   = (SELECT byc_cus_kode FROM 	bayarcus_hdr WHERE byc_nomor = p_byc_nomor);
  SET v_tgl   = (SELECT byc_tanggal  FROM 	bayarcus_hdr WHERE byc_nomor = p_byc_nomor);
  SET v_bayar = (SELECT bycd_bayar   FROM 	bayarcus_dtl  WHERE bycd_byc_nomor = p_byc_nomor
                                                    AND bycd_fp_nomor = p_fp_nomor);
  SET v_sls   = (SELECT s.so_sls_kode FROM 	fp_hdr f
                   LEFT JOIN 	do_hdr d ON d.do_nomor = f.fp_do_nomor
                   LEFT JOIN 	so_hdr s ON s.so_nomor = COALESCE(f.fp_so_nomor, d.do_so_nomor)
                  WHERE f.fp_nomor = p_fp_nomor);
  SET v_jt    = (SELECT fp_jthtempo FROM 	fp_hdr WHERE fp_nomor = p_fp_nomor);

  IF v_cus IS NOT NULL AND v_tgl IS NOT NULL AND v_jt IS NOT NULL AND v_bayar IS NOT NULL THEN
    SET v_jt = COALESCE(
      (SELECT MIN(j.jt_tanggaljt) FROM 	jatuhtempofp j
        WHERE j.jt_fp_nomor = p_fp_nomor AND j.jt_tanggaljt >= v_tgl),
      v_jt);

       v_cus, v_sls, p_byc_nomor, 0, v_bayar, v_tgl, v_jt, p_fp_nomor);
  END IF;
END//
DELIMITER ;

-- Dumping structure for procedure ampersada.sp_kp_fp
DELIMITER //
CREATE PROCEDURE `sp_kp_fp`(IN p_fp_nomor VARCHAR(20))
BEGIN
  DECLARE v_sls    VARCHAR(10);
  DECLARE v_cus    CHAR(10);
  DECLARE v_tgl    DATE;
  DECLARE v_jt     DATE;
  DECLARE v_amount DOUBLE;
  DECLARE v_cbg    VARCHAR(5);

  SET v_cbg = (SELECT cbg_kode FROM tcabang WHERE cbg_aktif = 1 LIMIT 1);
  
  

  DELETE FROM 	kartupiutang
   WHERE kp_src = CONCAT('FP|', p_fp_nomor)
      OR kp_src LIKE CONCAT('FJ|', p_fp_nomor, '|%');

  SET v_sls    = (SELECT s.so_sls_kode FROM 	fp_hdr f
                    LEFT JOIN 	do_hdr d ON d.do_nomor = f.fp_do_nomor
                    LEFT JOIN 	so_hdr s ON s.so_nomor = COALESCE(f.fp_so_nomor, d.do_so_nomor)
                   WHERE f.fp_nomor = p_fp_nomor);
  SET v_cus    = (SELECT fp_cus_kode  FROM 	fp_hdr WHERE fp_nomor = p_fp_nomor);
  SET v_tgl    = (SELECT fp_tanggal   FROM 	fp_hdr WHERE fp_nomor = p_fp_nomor);
  SET v_jt     = (SELECT fp_jthtempo  FROM 	fp_hdr WHERE fp_nomor = p_fp_nomor);
  SET v_amount = (SELECT fp_amount    FROM 	fp_hdr WHERE fp_nomor = p_fp_nomor);

  IF v_cus IS NOT NULL AND v_tgl IS NOT NULL AND v_jt IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM 	jatuhtempofp WHERE jt_fp_nomor = p_fp_nomor) THEN
      SELECT
        CONCAT('FJ|', j.jt_fp_nomor, '|', j.jt_tanggaljt),
        v_cus, v_sls, p_fp_nomor, j.jt_nilai, 0, v_tgl, j.jt_tanggaljt, p_fp_nomor
      FROM 	jatuhtempofp j
      WHERE j.jt_fp_nomor = p_fp_nomor;
    ELSE
    END IF;
  END IF;
END//
