CREATE PROCEDURE `sp_kp_rj`(IN p_retj_nomor VARCHAR(20))
BEGIN
  DECLARE v_sls VARCHAR(10);
  DECLARE v_cus CHAR(10);
  DECLARE v_tgl DATE;
  DECLARE v_jt  DATE;
  DECLARE v_amt DOUBLE;
  DECLARE v_fp  VARCHAR(20);

  DELETE FROM 	kartupiutang WHERE kp_src = CONCAT('RJ|', p_retj_nomor);

  SET v_cus = (SELECT retj_cus_kode FROM 	retj_hdr WHERE retj_nomor = p_retj_nomor);
  SET v_tgl = (SELECT retj_tanggal  FROM 	retj_hdr WHERE retj_nomor = p_retj_nomor);
  SET v_amt = (SELECT retj_amount   FROM 	retj_hdr WHERE retj_nomor = p_retj_nomor);
  SET v_fp  = (SELECT retj_fp_nomor FROM 	retj_hdr WHERE retj_nomor = p_retj_nomor);

  SET v_sls = (SELECT s.so_sls_kode FROM 	fp_hdr f
                 LEFT JOIN 	do_hdr d ON d.do_nomor = f.fp_do_nomor
                 LEFT JOIN 	so_hdr s ON s.so_nomor = COALESCE(f.fp_so_nomor, d.do_so_nomor)
                WHERE f.fp_nomor = v_fp);
  SET v_jt  = (SELECT fp_jthtempo FROM 	fp_hdr WHERE fp_nomor = v_fp);

  IF v_cus IS NOT NULL AND v_tgl IS NOT NULL AND v_jt IS NOT NULL AND v_amt IS NOT NULL THEN
    SET v_jt = COALESCE(
      (SELECT MIN(j.jt_tanggaljt) FROM 	jatuhtempofp j
        WHERE j.jt_fp_nomor = v_fp AND j.jt_tanggaljt >= v_tgl),
      v_jt);

  END IF;
END//
