-- Dumping structure for function ampersada.Terbilang
DELIMITER //
CREATE FUNCTION `Terbilang`(`_the_amount` DOUBLE) RETURNS varchar(250) CHARSET latin1 COLLATE latin1_swedish_ci
BEGIN



	DECLARE  _divisor	bigint;

	DECLARE	_large_amount	double;

	DECLARE	_tiny_amount	double;

	DECLARE	_dividen	double;

	DECLARE	_dummy		double;

	DECLARE	_the_word	varchar(250);

	DECLARE	_weight	varchar(100);

	DECLARE	_unit		varchar(30);

	DECLARE	_follower	varchar(50);

	DECLARE	_prefix	varchar(10);

	DECLARE	_sufix		varchar(10);



	SET _the_word = '';

	SET _large_amount = FLOOR(ABS(_the_amount) );

	SET _tiny_amount = ROUND((ABS(_the_amount) - _large_amount ) * 100.00,0);

	SET _divisor = 1000000000000.00;



	IF _large_amount >= _divisor * 1000.00 then

		RETURN 'OUT OF RANGE' ;

	END IF;

	WHILE _divisor >= 1 do

		BEGIN	

			SET _dividen = FLOOR(_large_amount / _divisor);

			SET _large_amount = CONVERT(_large_amount, signed) % _divisor;

		

			SET _unit = '';

			IF _dividen > 0.00 then

				CASE _divisor

					WHEN 1000000000000.00 THEN set _unit='TRILYUN ';

					WHEN 1000000000.00 THEN set _unit='MILYAR ';			

					WHEN 1000000.00 THEN set _unit='JUTA ';				

					WHEN 1000.00 THEN set _unit='RIBU ';

					ELSE Set _unit='';

				END CASE;

			end if;



			SET _weight = '';

			SET _dummy = _dividen;

			IF _dummy >= 100.00 then

					CASE FLOOR(_dummy / 100.00)

						WHEN 1 THEN SET _weight ='SERATUS ';

						WHEN 2 THEN SET _weight ='DUA RATUS ';

						WHEN 3 THEN SET _weight ='TIGA RATUS ';

						WHEN 4 THEN SET _weight ='EMPAT RATUS ';

						WHEN 5 THEN SET _weight ='LIMA RATUS ';

						WHEN 6 THEN SET _weight ='ENAM RATUS ';

						WHEN 7 THEN SET _weight ='TUJUH RATUS ';

						WHEN 8 THEN SET _weight ='DELAPAN RATUS ';

						ELSE SET _weight ='SEMBILAN RATUS ';

					END CASE;

			end if;

			

			SET _dummy = CONVERT(_dividen, signed) % 100;

			IF _dummy < 10.00 then

				begin			

					IF _dummy = 1.00 AND _unit = 'RIBU' then

						begin					

							IF _dividen=_dummy then

								SET _weight = CONCAT(_weight , 'SE');

							ELSE

								SET _weight = CONCAT(_weight , 'SATU ');

							END IF;

						end;	

					ELSE

						IF _dummy > 0.00 then

							CASE _dummy

								WHEN 1 THEN SET _weight = CONCAT(_weight , 'SATU ');

								WHEN 2 THEN SET _weight = CONCAT(_weight , 'DUA ');

								WHEN 3 THEN SET _weight = CONCAT(_weight , 'TIGA ');

								WHEN 4 THEN SET _weight = CONCAT(_weight , 'EMPAT ');

								WHEN 5 THEN SET _weight = CONCAT(_weight , 'LIMA ');

								WHEN 6 THEN SET _weight = CONCAT(_weight , 'ENAM ');

								WHEN 7 THEN SET _weight = CONCAT(_weight , 'TUJUH ');

								WHEN 8 THEN SET _weight = CONCAT(_weight , 'DELAPAN ');

								ELSE SET _weight = CONCAT(_weight , 'SEMBILAN ');

							END CASE;

						END IF;	

					END IF;	

				end;	

			ELSE

				IF _dummy BETWEEN 11 AND 19 then

					CASE CONVERT(_dummy,signed) % 10 

						WHEN 1 THEN SET _weight = CONCAT(_weight , 'SEBELAS ');

						WHEN 2 THEN SET _weight = CONCAT(_weight , 'DUA BELAS ');

						WHEN 3 THEN SET _weight = CONCAT(_weight , 'TIGA BELAS ');

						WHEN 4 THEN SET _weight = CONCAT(_weight , 'EMPAT BELAS ');

						WHEN 5 THEN SET _weight = CONCAT(_weight , 'LIMA BELAS ');

						WHEN 6 THEN SET _weight = CONCAT(_weight , 'ENAM BELAS ');

						WHEN 7 THEN SET _weight = CONCAT(_weight , 'TUJUH BELAS ');

						WHEN 8 THEN SET _weight = CONCAT(_weight , 'DELAPAN BELAS ');

						ELSE SET _weight = CONCAT(_weight , 'SEMBILAN BELAS ') ;

					END CASE;

				ELSE

					begin				

						CASE FLOOR(_dummy / 10) 

							WHEN 1 THEN SET _weight = CONCAT(_weight , 'SEPULUH ');

							WHEN 2 THEN SET _weight = CONCAT(_weight , 'DUA PULUH ');

							WHEN 3 THEN SET _weight = CONCAT(_weight , 'TIGA PULUH ');

							WHEN 4 THEN SET _weight = CONCAT(_weight , 'EMPAT PULUH ');

							WHEN 5 THEN SET _weight = CONCAT(_weight , 'LIMA PULUH ');

							WHEN 6 THEN SET _weight = CONCAT(_weight , 'ENAM PULUH ');

							WHEN 7 THEN SET _weight = CONCAT(_weight , 'TUJUH PULUH ');

							WHEN 8 THEN SET _weight = CONCAT(_weight , 'DELAPAN PULUH ');

							ELSE SET _weight = CONCAT(_weight , 'SEMBILAN PULUH ');

						END CASE;

						IF CONVERT(_dummy,signed) % 10 > 0 then

							CASE CONVERT(_dummy,signed) % 10 

								WHEN 1 THEN SET _weight = CONCAT(_weight , 'SATU ');

								WHEN 2 THEN SET _weight = CONCAT(_weight , 'DUA ');

								WHEN 3 THEN SET _weight = CONCAT(_weight , 'TIGA ');

								WHEN 4 THEN SET _weight = CONCAT(_weight , 'EMPAT ');

								WHEN 5 THEN SET _weight = CONCAT(_weight , 'LIMA ');

								WHEN 6 THEN SET _weight = CONCAT(_weight , 'ENAM ');

								WHEN 7 THEN SET _weight = CONCAT(_weight , 'TUJUH ');

								WHEN 8 THEN SET _weight = CONCAT(_weight , 'DELAPAN ');

								ELSE SET _weight = CONCAT(_weight , 'SEMBILAN ');

							END CASE;

						END IF;	

					END;

				END IF;

			END IF;	

		end;	

		SET _the_word = CONCAT(_the_word , _weight , _unit);

		SET _divisor = _divisor / 1000.00;

	end while;

	

	IF FLOOR(_the_amount) = 0.00 then

		SET _the_word = 'NOL ';

	END IF;

	SET _follower = '';

	IF _tiny_amount < 10.00 then

		BEGIN	

			IF _tiny_amount > 0.00 then

				begin

					CASE _tiny_amount

							WHEN 1 THEN SET _follower = 'SATU ';

							WHEN 2 THEN SET _follower = 'DUA ';

							WHEN 3 THEN SET _follower = 'TIGA ';

							WHEN 4 THEN SET _follower = 'EMPAT ';

							WHEN 5 THEN SET _follower = 'LIMA ';

							WHEN 6 THEN SET _follower = 'ENAM ';

							WHEN 7 THEN SET _follower = 'TUJUH ';

							WHEN 8 THEN SET _follower = 'DELAPAN ';

							ELSE SET _follower = 'SEMBILAN ';

						END CASE;

						SET _follower = concat('KOMA NOL ', _follower);											

				end;	

			END IF;		

		END;

	ELSE

		BEGIN

			CASE FLOOR(_tiny_amount / 10.00)

				WHEN 1 THEN SET _follower = 'SATU ';

				WHEN 2 THEN SET _follower = 'DUA ';

				WHEN 3 THEN SET _follower = 'TIGA ';

				WHEN 4 THEN SET _follower = 'EMPAT ';

				WHEN 5 THEN SET _follower = 'LIMA ';

				WHEN 6 THEN SET _follower = 'ENAM ';

				WHEN 7 THEN SET _follower = 'TUJUH ';

				WHEN 8 THEN SET _follower = 'DELAPAN ';

				ELSE SET _follower = 'SEMBILAN ';

			END CASE;

			SET _follower = concat('KOMA ',_follower);

			IF CONVERT(_tiny_amount,signed int) % 10 > 0 then

				CASE CONVERT(_tiny_amount,signed int) % 10

					WHEN 1 THEN SET _follower = CONCAT(_follower , 'SATU ');

					WHEN 2 THEN SET _follower = CONCAT(_follower , 'DUA ');

					WHEN 3 THEN SET _follower = CONCAT(_follower , 'TIGA ');

					WHEN 4 THEN SET _follower = CONCAT(_follower , 'EMPAT ');

					WHEN 5 THEN SET _follower = CONCAT(_follower , 'LIMA ');

					WHEN 6 THEN SET _follower = CONCAT(_follower , 'ENAM ');

					WHEN 7 THEN SET _follower = CONCAT(_follower , 'TUJUH ');

					WHEN 8 THEN SET _follower = CONCAT(_follower , 'DELAPAN ');

					ELSE SET _follower = CONCAT(_follower , 'SEMBILAN ');

				END CASE;

			END IF	;

		END ;

	END IF;

	SET _the_word = CONCAT(_the_word , _follower);



	IF _the_amount < 0.00 then	

		SET _the_word = CONCAT('MINUS ' , _the_word);

	END IF;

	RETURN _the_word;

END//
DELIMITER ;

